31	class Plugin {
32	  Plugin({
33	    @required this.name,
34	    @required this.path,
35	    @required this.platforms,
36	    @required this.dependencies,
37	  }) : assert(name != null),
38	       assert(path != null),
39	       assert(platforms != null),
40	       assert(dependencies != null);
41	
42	  /// Parses [Plugin] specification from the provided pluginYaml.
43	  ///
44	  /// This currently supports two formats. Legacy and Multi-platform.
45	  ///
46	  /// Example of the deprecated Legacy format.
47	  ///
48	  ///     flutter:
49	  ///      plugin:
50	  ///        androidPackage: io.flutter.plugins.sample
51	  ///        iosPrefix: FLT
52	  ///        pluginClass: SamplePlugin
53	  ///
54	  /// Example Multi-platform format.
55	  ///
56	  ///     flutter:
57	  ///      plugin:
58	  ///        platforms:
59	  ///          android:
60	  ///            package: io.flutter.plugins.sample
61	  ///            pluginClass: SamplePlugin
62	  ///          ios:
63	  ///            pluginClass: SamplePlugin
64	  ///          linux:
65	  ///            pluginClass: SamplePlugin
66	  ///          macos:
67	  ///            pluginClass: SamplePlugin
68	  ///          windows:
69	  ///            pluginClass: SamplePlugin
70	  factory Plugin.fromYaml(
71	    String name,
72	    String path,
73	    YamlMap pluginYaml,
74	    List<String> dependencies,
75	  ) {
76	    final List<String> errors = validatePluginYaml(pluginYaml);
77	    if (errors.isNotEmpty) {
78	      throwToolExit('Invalid plugin specification $name.\n${errors.join('\n')}');
79	    }
80	    if (pluginYaml != null && pluginYaml['platforms'] != null) {
81	      return Plugin._fromMultiPlatformYaml(name, path, pluginYaml, dependencies);
82	    }
83	    return Plugin._fromLegacyYaml(name, path, pluginYaml, dependencies);
84	  }
